<script setup lang="ts">
import { computed,onMounted,onUnmounted,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { api,uploadEvidence,apiBlob,useLoad,useCommand,money,cents,PageHeader,Feedback,StatusBadge,type Order,type Preview,type Aftersale,type Allocation } from '@tradeflow/ui'
import { pathNo } from '../state'
import CreateRequestRecovery from '../components/CreateRequestRecovery.vue'
const no=String(useRoute().params.no),router=useRouter(),type=ref(''),reason=ref(''),error=ref(''),preview=ref<Preview|null>(null),previewBusy=ref(false),uploadBusy=ref(false),evidence=ref<{objectKey:string;url:string;name:string}[]>([])
const amounts=ref<Record<string,string>>({}),selected=ref<string[]>([]),load=useLoad<Order>(s=>api(`/orders/${pathNo(no)}`,{signal:s})),command=useCommand(`user-aftersale-create:${no}`)
// 退货申请最多5张，为商家拒收验收保留至少1张；仅退款最多6张，与后端证据总额契约一致。
const maxEvidence=computed(()=>type.value==='RETURN_REFUND'?5:6)
const labels:Record<string,string>={UNSHIPPED_FULL:'未发货整单退款',REFUND_ONLY:'仅退款（可申请部分金额）',RETURN_REFUND:'退货退款（剩余可退金额）'}
const types=computed(()=>['UNSHIPPED_FULL','REFUND_ONLY','RETURN_REFUND'].filter(t=>load.data.value?.allowedActions?.includes(t)))
const units=computed(()=>load.data.value?.items.flatMap(i=>i.units.map(u=>({...u,orderItemId:i.orderItemId,productName:i.productName,specification:i.specification,key:`${i.orderItemId}:${u.unitNo}`}))) || [])
const requestVersion=ref(0);let alive=true,previewController:AbortController|null=null
onMounted(async()=>{await load.reload();if(alive)type.value=types.value[0] || ''})
watch([type,selected,amounts],()=>{preview.value=null;requestVersion.value++;previewBusy.value=false;previewController?.abort()},{deep:true})
onUnmounted(()=>{alive=false;previewController?.abort();evidence.value.forEach(e=>URL.revokeObjectURL(e.url))})
// 金额按十进制元字符串转换整数分；仅退款逐件自选部分金额，退货取该件剩余额度。
function allocations():Allocation[]{if(type.value==='UNSHIPPED_FULL')return [];if(!selected.value.length)throw new Error('请至少选择一件商品');return selected.value.map(key=>{const u=units.value.find(x=>x.key===key);if(!u)throw new Error('购买件已变化，请刷新订单');const amount=type.value==='RETURN_REFUND'?u.remainingRefundCents:cents(amounts.value[key] || '');if(amount<=0||amount>u.remainingRefundCents)throw new Error('逐件退款金额应大于0且不超过剩余可退金额');return {orderItemId:u.orderItemId,unitNo:u.unitNo,amountCents:amount}})}
// 预览不预占权益；任何分配修改立即作废预览，创建仍由服务端重新校验。
async function check(){
 error.value='';preview.value=null;previewController?.abort();previewController=new AbortController()
 const signal=previewController.signal,version=++requestVersion.value;previewBusy.value=true
 try{const body={orderNo:no,type:type.value,allocations:allocations()};const result=await api<Preview>('/aftersales/preview',{method:'POST',body,signal});if(alive&&!signal.aborted&&version===requestVersion.value)preview.value=result}
 catch(e){if(alive&&!signal.aborted&&version===requestVersion.value)error.value=(e as Error).message}
 finally{if(alive&&version===requestVersion.value)previewBusy.value=false}
}
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;error.value='';if(evidence.value.length>=maxEvidence.value){error.value=`当前类型最多上传${maxEvidence.value}张证据`;return}uploadBusy.value=true;try{const result=await uploadEvidence(file);if(!alive)return;const blob=await apiBlob(`/evidence-files/${pathNo(result.objectKey)}`);if(!alive)return;const url=URL.createObjectURL(blob);evidence.value.push({objectKey:result.objectKey,url,name:file.name})}catch(e){if(alive)error.value=(e as Error).message}finally{if(alive)uploadBusy.value=false;input.value=''}}
function remove(index:number){const e=evidence.value.splice(index,1)[0];if(e)URL.revokeObjectURL(e.url)}
async function submit(){if(!preview.value||!reason.value.trim()||evidence.value.length>maxEvidence.value)return;error.value='';const body={orderNo:no,type:type.value,reason:reason.value.trim(),allocations:preview.value.allocations,evidenceKeys:evidence.value.map(e=>e.objectKey)};const result=await command.run<Aftersale>('create',body,key=>api('/aftersales',{method:'POST',body,key}));if(result&&alive){await command.reset();if(!alive)return;await router.push(`/aftersales/${pathNo(result.aftersaleNo)}`)}}
</script>
<template><section><RouterLink class="back-link" :to="`/orders/${pathNo(no)}`">← 返回订单</RouterLink><PageHeader title="申请售后" description="先核对购买件与金额，再提交申请。预览不会锁定退款权益。"/><Feedback :error="load.error.value || error || command.error.value" :loading="load.loading.value"/><CreateRequestRecovery :order-no="no" kind="aftersale" :activity="command.busy.value"/><div v-if="load.data.value" class="two-col"><form @submit.prevent="submit"><div class="panel"><h2>1. 选择售后类型</h2><label for="aftersale-type">当前可申请类型</label><select id="aftersale-type" v-model="type" required><option v-if="!types.length" value="">当前没有可申请类型</option><option v-for="t in types" :key="t" :value="t">{{labels[t]}}</option></select><p class="muted small">未发货整单退款由服务器自动分配整单剩余实付；仅退款不增加库存。退货退款按所选购买件剩余实付申请。</p></div><div v-if="type && type!=='UNSHIPPED_FULL'" class="panel"><h2>2. 选择购买件</h2><div v-for="u in units" :key="u.key" class="allocation-row"><label class="checkbox-label"><input v-model="selected" :value="u.key" type="checkbox" :disabled="u.hasActiveAftersale || u.reservedRefundCents>0 || u.remainingRefundCents<=0 || u.returnState!=='NONE'"/><span>{{u.productName}} · {{u.specification}} · 第{{u.unitNo}}件</span></label><p class="small muted">剩余可退 {{money(u.remainingRefundCents)}} · 已退 {{money(u.succeededRefundCents)}} · {{u.hasActiveAftersale?'已有进行中售后':'无进行中售后'}} · 退货状态 {{u.returnState}}</p><div v-if="selected.includes(u.key) && type==='REFUND_ONLY'"><label :for="`amount-${u.key}`">本件申请金额（元）</label><input :id="`amount-${u.key}`" v-model="amounts[u.key]" inputmode="decimal" placeholder="例如 12.50"/></div></div></div><div class="panel"><h2>3. 原因与证据</h2><label for="aftersale-reason">申请原因</label><textarea id="aftersale-reason" v-model.trim="reason" maxlength="255" required placeholder="请说明遇到的问题和诉求"/><label for="evidence-upload">图片证据（可选，最多{{maxEvidence}}张）</label><input id="evidence-upload" type="file" accept="image/jpeg,image/png,image/webp" :disabled="uploadBusy || evidence.length>=maxEvidence" @change="upload"/><p v-if="uploadBusy" role="status">正在受控上传并读取证据…</p><div class="evidence-grid"><figure v-for="(e,index) in evidence" :key="e.objectKey"><img :src="e.url" :alt="e.name"/><figcaption>{{e.name}}</figcaption><button type="button" @click="remove(index)">移除证据</button></figure></div></div><button class="primary" :disabled="!preview || !reason.trim() || command.busy.value || uploadBusy || evidence.length>maxEvidence">提交售后申请</button></form><aside class="panel summary"><span class="eyebrow">申请金额核对</span><h2>提交前，先预览</h2><p class="muted">金额与可用权益以服务器本次预览为准，提交时会再次检查。</p><button class="secondary full" :disabled="!type || previewBusy || command.busy.value" @click="check">{{previewBusy?'正在核对…':'预览退款分配'}}</button><template v-if="preview"><strong class="large-price">{{money(preview.amountCents)}}</strong><p class="small muted">{{preview.allocations.length}} 个购买件</p><div v-for="a in preview.allocations" :key="`${a.orderItemId}:${a.unitNo}`" class="unit-row">商品项 {{a.orderItemId}} · 第{{a.unitNo}}件<br/><strong>{{money(a.amountCents)}}</strong></div><StatusBadge status="PREVIEW"/><p class="small muted">预览已取得，尚未创建售后。</p></template></aside></div></section></template>

